/**
 * Unit tests for the divide method of the Fraction class.
 */
public class Fraction_divide_TriageGen2Test {

    @Test
    public void testDivide_ValidFraction() {
        // Test case: 1/2 divided by 3/4 should be 1/2 * 4/3 = 4/6 = 2/3
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(3, 4);
        Fraction expected = new Fraction(2, 3);
        Fraction result = f1.divide(f2);

        Assert.assertEquals("The result of division should be correct", expected, result);
    }










}

